INSERT INTO "gigs" ("id", "slug", "title", "description", "coverColor", "published", "sellerId", "categoryId", "createdAt", "updatedAt")
VALUES
  ('gig-yazi-ceviri-ing-001', 'i-ngilizce-turkce-profesyonel-ceviri-yapiyorum', 'İngilizce-Türkçe profesyonel çeviri yapıyorum', 'Teknik dokümanlar, web siteleri ve pazarlama metinlerinizi anlam bütünlüğünü koruyarak İngilizce-Türkçe çeviriyorum.', 'violet', true, (SELECT id FROM "users" WHERE email = 'asli@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'yazi-ceviri'), now(), now()),
  ('gig-video-2d-intro-001', '2d-logo-animasyonu-ve-marka-intro-su-hazirliyorum', '2D logo animasyonu ve marka intro''su hazırlıyorum', 'Markanızın logosunu akıcı bir 2D animasyona dönüştürüp video içeriklerinizin başına eklenecek profesyonel bir intro hazırlıyorum.', 'emerald', true, (SELECT id FROM "users" WHERE email = 'zeynep@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'video-animasyon'), now(), now()),
  ('gig-muzik-podcast-001', 'podcast-ve-video-icin-ses-miksaji-ve-duzenleme-yapiyorum', 'Podcast ve video için ses miksajı ve düzenleme yapıyorum', 'Ham ses kayıtlarınızı gürültüden arındırıp seviye dengelemesi yaparak yayına hazır, temiz bir mikse dönüştürüyorum.', 'indigo', true, (SELECT id FROM "users" WHERE email = 'zeynep@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'muzik-ses'), now(), now()),
  ('gig-muzik-sosyal-001', 'sosyal-medya-videolariniz-icin-muzik-ve-seslendirme-buluyorum', 'Sosyal medya videolarınız için müzik ve seslendirme buluyorum', 'İçeriğinizin tonuna uygun telifsiz müzik seçimi yapıyor, gerektiğinde kısa seslendirme kaydı da sağlıyorum.', 'rose', true, (SELECT id FROM "users" WHERE email = 'elif@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'muzik-ses'), now(), now()),
  ('gig-danismanlik-pazarlama-001', 'kucuk-isletmeler-icin-pazarlama-stratejisi-danismanligi-veriyorum', 'Küçük işletmeler için pazarlama stratejisi danışmanlığı veriyorum', 'İşletmenizin hedef kitlesini, rakiplerini ve kanallarını analiz ederek uygulanabilir bir pazarlama yol haritası çıkarıyorum.', 'amber', true, (SELECT id FROM "users" WHERE email = 'burak@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'is-danismanlik'), now(), now()),
  ('gig-danismanlik-teknik-001', 'yazilim-projeniz-icin-teknik-danismanlik-ve-kod-incelemesi-yapiyorum', 'Yazılım projeniz için teknik danışmanlık ve kod incelemesi yapıyorum', 'Mevcut kod tabanınızı inceleyip mimari, performans ve güvenlik açısından somut iyileştirme önerileri sunuyorum.', 'sky', true, (SELECT id FROM "users" WHERE email = 'mert@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'is-danismanlik'), now(), now()),
  ('gig-egitim-seo-001', 'i-cerik-yazarligi-ve-seo-uzerine-birebir-online-ders-veriyorum', 'İçerik yazarlığı ve SEO üzerine birebir online ders veriyorum', 'SEO uyumlu içerik yazımının temellerini, anahtar kelime araştırmasını ve yazı planlamasını birebir canlı derste anlatıyorum.', 'violet', true, (SELECT id FROM "users" WHERE email = 'asli@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'egitim-ders'), now(), now()),
  ('gig-egitim-tasarim-001', 'grafik-tasarim-temelleri-online-egitimi-veriyorum', 'Grafik tasarım temelleri online eğitimi veriyorum', 'Tipografi, renk teorisi ve kompozisyon temellerini örneklerle anlatan, yeni başlayanlara yönelik birebir eğitim veriyorum.', 'amber', true, (SELECT id FROM "users" WHERE email = 'can@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'egitim-ders'), now(), now()),
  ('gig-ai-zapier-001', 'zapier-make-ile-is-sureclerinizi-otomatiklestiriyorum', 'Zapier & Make ile iş süreçlerinizi otomatikleştiriyorum', 'Tekrar eden manuel işlerinizi Zapier veya Make üzerinde kurduğum otomasyon akışlarıyla ortadan kaldırıyorum.', 'indigo', true, (SELECT id FROM "users" WHERE email = 'deniz@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'ai-otomasyon'), now(), now()),
  ('gig-ai-chatbot-001', 'chatgpt-claude-entegrasyonlu-ai-chatbot-gelistiriyorum', 'ChatGPT/Claude entegrasyonlu AI chatbot geliştiriyorum', 'Web siteniz veya WhatsApp hattınız için müşteri sorularını yanıtlayan, kendi verilerinizle eğitilmiş bir AI chatbot geliştiriyorum.', 'sky', true, (SELECT id FROM "users" WHERE email = 'deniz@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'ai-otomasyon'), now(), now()),
  ('gig-veri-analiz-001', 'i-sletmeniz-icin-satis-ve-pazarlama-verilerini-analiz-ediyorum', 'İşletmeniz için satış ve pazarlama verilerini analiz ediyorum', 'Ham verilerinizi düzenleyip anlamlı içgörülere dönüştürerek karar alma sürecinize somut veri desteği sağlıyorum.', 'emerald', true, (SELECT id FROM "users" WHERE email = 'ayse@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'veri-analitik'), now(), now()),
  ('gig-veri-dashboard-001', 'excel-power-bi-ile-interaktif-veri-paneli-dashboard-hazirliyorum', 'Excel/Power BI ile interaktif veri paneli (dashboard) hazırlıyorum', 'Verilerinizi canlı güncellenen, filtrelenebilir bir Power BI veya Excel panelinde tek bakışta takip edilebilir hale getiriyorum.', 'violet', true, (SELECT id FROM "users" WHERE email = 'ayse@profestia.dev'), (SELECT id FROM "categories" WHERE slug = 'veri-analitik'), now(), now())
